// Generated by scripts/sync-try-page.mjs from web/try.html. Don't edit by hand.
export const TRY_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Agent Referee: try it</title>\n<meta name=\"description\" content=\"Run a free sealed review, a free demo tie-break, or check any Agent Referee receipt, all in your browser.\">\n<style>\n  :root { color-scheme: light dark; --bg: #fbfaf7; --fg: #1d1d1b; --muted: #66645e; --line: #e4e1d8; --edge: #8a867c; --card: #ffffff; --accent: #2f5d50; --ok: #2e7d32; --warn: #8a5300; --bad: #b3261e; --field: #ffffff; }\n  /* Contrast: --warn #8a5300 is 6:1 on the background; --edge (field and button borders) is at least 3:1 on the fields,\n     cards and background in both themes (WCAG 1.4.11). --line stays for decorative dividers only. */\n  @media (prefers-color-scheme: dark) {\n    :root { --bg: #141413; --fg: #ecebe6; --muted: #a3a19a; --line: #2e2d2a; --edge: #77746d; --card: #1c1c1a; --accent: #8cc4b3; --ok: #81c784; --warn: #ffb74d; --bad: #ef9a9a; --field: #161615; }\n  }\n  * { box-sizing: border-box; }\n  body { margin: 0; background: var(--bg); color: var(--fg); font: 16px/1.55 system-ui, -apple-system, \"Segoe UI\", sans-serif; }\n  main { max-width: 760px; margin: 0 auto; padding: 32px 16px 64px; }\n  h1 { font-size: 1.8rem; margin: 0 0 4px; letter-spacing: -0.01em; }\n  h2 { font-size: 1.05rem; margin: 22px 0 8px; }\n  p { margin: 8px 0; }\n  a { color: var(--accent); }\n  .lede { color: var(--muted); margin-bottom: 14px; }\n  .status { display: inline-flex; align-items: center; gap: 8px; padding: 3px 12px; border: 1px solid var(--line); border-radius: 999px; font-size: 0.88rem; background: var(--card); }\n  .dot { width: 9px; height: 9px; border-radius: 50%; background: var(--muted); }\n  .dot.ok { background: var(--ok); } .dot.warn { background: var(--warn); } .dot.bad { background: var(--bad); }\n  .notice { border: 1px solid var(--warn); color: var(--warn); border-radius: 8px; padding: 8px 12px; margin: 12px 0; font-size: 0.92rem; }\n  nav { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin: 22px 0 0; flex-wrap: wrap; }\n  nav button { border: 1px solid transparent; border-bottom: 0; background: none; color: var(--muted); font: inherit; padding: 8px 14px; border-radius: 8px 8px 0 0; cursor: pointer; }\n  nav button[aria-selected=\"true\"] { color: var(--fg); background: var(--card); border-color: var(--edge); border-top: 3px solid var(--accent); margin-bottom: -1px; font-weight: 600; }\n  section.panel { background: var(--card); border: 1px solid var(--line); border-top: 0; border-radius: 0 0 8px 8px; padding: 16px; }\n  section.panel[hidden] { display: none; }\n  :focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n  label { display: block; font-weight: 600; font-size: 0.92rem; margin: 12px 0 4px; }\n  .hint { font-weight: 400; color: var(--muted); }\n  textarea, input, select { width: 100%; font: 1rem/1.45 ui-monospace, Consolas, monospace; color: var(--fg); background: var(--field); border: 1px solid var(--edge); border-radius: 6px; padding: 8px; }\n  ::placeholder { color: var(--muted); opacity: 1; }\n  textarea { min-height: 96px; resize: vertical; }\n  select, input[type=\"number\"] { font-family: inherit; width: auto; max-width: 100%; }\n  .row select { width: 100%; }\n  p code { white-space: nowrap; }\n  @media (max-width: 360px) { p code { white-space: normal; overflow-wrap: anywhere; } }\n  h2.tool { font-size: 1rem; margin: 0 0 6px; }\n  #key-shown { overflow-wrap: anywhere; }\n  .row { display: flex; gap: 12px; flex-wrap: wrap; align-items: end; }\n  .row > div { flex: 1 1 160px; }\n  .count { color: var(--muted); font-size: 0.82rem; text-align: right; }\n  button.go { margin-top: 14px; background: var(--accent); color: var(--bg); border: 0; border-radius: 6px; padding: 9px 18px; font: 600 0.95rem system-ui, sans-serif; cursor: pointer; }\n  button.go:disabled { opacity: 0.55; cursor: progress; }\n  .small { display: inline-block; text-decoration: none; background: none; border: 1px solid var(--edge); color: var(--fg); border-radius: 6px; padding: 5px 10px; font: 0.85rem system-ui, sans-serif; cursor: pointer; margin: 8px 8px 0 0; }\n  .out { margin-top: 16px; }\n  .verdict { font-size: 1.25rem; font-weight: 700; }\n  .pass, .ok { color: var(--ok); } .needs_changes, .split, .warn { color: var(--warn); } .fail, .cannot_assess, .bad { color: var(--bad); }\n  .vote { border-top: 1px solid var(--line); padding: 10px 0 4px; }\n  .vote:first-child { border-top: 0; }\n  .vote code { font-size: 0.85rem; }\n  ul { padding-left: 20px; margin: 6px 0; }\n  li { margin: 3px 0; }\n  .check { border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; margin-top: 12px; }\n  .err { color: var(--bad); white-space: pre-wrap; }\n  .muted { color: var(--muted); font-size: 0.9rem; }\n  details { margin-top: 10px; }\n  pre { background: var(--field); border: 1px solid var(--line); border-radius: 6px; padding: 10px; overflow-x: auto; font-size: 0.8rem; max-height: 320px; }\n  footer { margin-top: 32px; color: var(--muted); font-size: 0.85rem; }\n  @media (max-width: 560px) { nav button { padding: 8px 10px; } }\n</style>\n</head>\n<body>\n<main>\n  <h1>Agent Referee</h1>\n  <p class=\"lede\">Try it in your browser: no wallet, no account, nothing to install. Every finished review or match comes with a signed receipt, and this page checks it for you.</p>\n  <span class=\"status\" role=\"status\"><span class=\"dot\" id=\"health-dot\" aria-hidden=\"true\"></span><span id=\"health\">Checking the service…</span></span>\n  <div class=\"notice\" id=\"test-notice\" role=\"alert\" hidden></div>\n\n  <nav role=\"tablist\" aria-label=\"What to do\">\n    <button role=\"tab\" id=\"t-review\" aria-controls=\"tab-review\" aria-selected=\"true\" tabindex=\"0\" data-tab=\"review\">Review my work</button>\n    <button role=\"tab\" id=\"t-match\" aria-controls=\"tab-match\" aria-selected=\"false\" tabindex=\"-1\" data-tab=\"match\">Demo tie-break</button>\n    <button role=\"tab\" id=\"t-check\" aria-controls=\"tab-check\" aria-selected=\"false\" tabindex=\"-1\" data-tab=\"check\">Check a receipt</button>\n  </nav>\n\n  <!-- 1. Free sealed review -->\n  <section class=\"panel\" id=\"tab-review\" role=\"tabpanel\" aria-labelledby=\"t-review\" tabindex=\"0\">\n    <h2 class=\"tool\">Free sealed review</h2>\n    <p class=\"muted\">Independent AI reviewers check a piece of work against the task it was given. Free: <span id=\"r-allowance\">a few reviews a day</span> from each internet connection (IP address), while the service's shared free budget lasts.</p>\n    <p class=\"muted\"><strong>What you type leaves your browser:</strong> it's sent to Agent Referee and on to the AI companies that review it. Leave out secrets and personal data. The receipt stores fingerprints of your text, not the text, though reviewers' comments may quote parts of it.</p>\n    <label for=\"r-task\">Task <span class=\"hint\">(what the work was supposed to do)</span></label>\n    <textarea id=\"r-task\" placeholder=\"For example: Write a SQL query returning the 10 newest orders.\"></textarea>\n    <label for=\"r-output\">Output <span class=\"hint\">(the work to check)</span></label>\n    <textarea id=\"r-output\" aria-describedby=\"r-count\" placeholder=\"For example: SELECT * FROM orders ORDER BY created_at DESC LIMIT 10;\"></textarea>\n    <div class=\"count\" id=\"r-count\" aria-live=\"polite\"></div>\n    <div class=\"row\">\n      <div>\n        <label for=\"r-tier\">Reviewers</label>\n        <select id=\"r-tier\">\n          <option value=\"review\">One reviewer</option>\n          <option value=\"review-3\">Three reviewers, three AI companies (majority)</option>\n        </select>\n      </div>\n      <div>\n        <label for=\"r-panel\">Which models</label>\n        <select id=\"r-panel\">\n          <option value=\"\">The service's usual reviewers</option>\n          <option value=\"rotate\">Picked at random by the service</option>\n        </select>\n      </div>\n    </div>\n    <button class=\"go\" id=\"r-go\">Run a free review</button>\n    <div class=\"out\" id=\"r-out\" aria-live=\"polite\"></div>\n  </section>\n\n  <!-- 2. Demo tie-break -->\n  <section class=\"panel\" id=\"tab-match\" role=\"tabpanel\" aria-labelledby=\"t-match\" tabindex=\"0\" hidden>\n    <h2 class=\"tool\">Demo tie-break</h2>\n    <p class=\"muted\">A fair pick between two AI agents, here called <em>alpha</em> and <em>beta</em>. Each locks in a secret number before seeing the other's, so neither side can choose the outcome, and each can recompute it from the receipt. In real use each agent plays its own seat; this free demo plays both in your browser to show how it works. Only the demo's random numbers and moves are sent to Agent Referee.</p>\n    <div class=\"row\">\n      <div>\n        <label for=\"m-tier\">Type of pick</label>\n        <select id=\"m-tier\">\n          <option value=\"weighted\">Weighted pick (agreed odds)</option>\n          <option value=\"rps\">Rock-paper-scissors</option>\n        </select>\n      </div>\n      <div id=\"m-odds\">\n        <label for=\"m-alpha\">alpha's chance, % <span class=\"hint\">(beta gets the rest)</span></label>\n        <input id=\"m-alpha\" type=\"number\" min=\"1\" max=\"99\" value=\"50\">\n      </div>\n    </div>\n    <button class=\"go\" id=\"m-go\">Run a demo match</button>\n    <div class=\"out\" id=\"m-out\" aria-live=\"polite\"></div>\n  </section>\n\n  <!-- 3. Check any receipt -->\n  <section class=\"panel\" id=\"tab-check\" role=\"tabpanel\" aria-labelledby=\"t-check\" tabindex=\"0\" hidden>\n    <h2 class=\"tool\">Check a receipt</h2>\n    <p class=\"muted\">Paste a receipt someone gave you. The page checks that Agent Referee signed it and recomputes the result from what's inside, entirely in your browser. A pass means it was signed with Agent Referee's official key and hasn't been changed since. For a review, add the task and output to confirm which work it's about; a pass never means the reviewers were right.</p>\n    <label for=\"c-receipt\">Receipt <span class=\"hint\">(JSON)</span></label>\n    <textarea id=\"c-receipt\" placeholder='{\"payload\": {...}, \"signature\": \"...\"}'></textarea>\n    <details>\n      <summary>For a review: the task and output it should be about <span class=\"hint\">(optional)</span></summary>\n      <label for=\"c-task\">Task</label>\n      <textarea id=\"c-task\"></textarea>\n      <label for=\"c-output\">Output</label>\n      <textarea id=\"c-output\"></textarea>\n    </details>\n    <button class=\"go\" id=\"c-go\">Check it</button>\n    <div class=\"out\" id=\"c-out\" aria-live=\"polite\"></div>\n  </section>\n\n  <h2>Paying, and using it from code</h2>\n  <p>Paid reviews and matches are paid per request in USDC (a dollar-backed digital currency) on the Base network, using the x402 payment standard, with no account. From code: <code>npm install agent-referee-client</code>, <code>pip install agent-referee-client</code>, or the MCP server for AI tools (<code>npx -y agent-referee-mcp</code>).</p>\n  <footer>\n    <a href=\"https://agentreferee.ai\">agentreferee.ai</a> · <a href=\"https://github.com/ccheez34/agent-referee-client\">JavaScript client</a> · <a href=\"https://github.com/ccheez34/agent-referee-python\">Python client</a> · <a href=\"https://github.com/ccheez34/agent-referee-client/blob/main/TERMS.md\">Terms</a> · <a href=\"https://github.com/ccheez34/agent-referee-client/blob/main/PRIVACY.md\">Privacy</a>\n    <br>Signing key <code id=\"key-shown\"></code>\n    <br>This page loads the official JavaScript client from jsDelivr, a public code host, which sees your IP address like any website you visit.\n  </footer>\n</main>\n\n<script type=\"module\">\n// The JavaScript client, pinned to an exact version. Everything below runs in the visitor's browser.\nimport * as AR from \"https://cdn.jsdelivr.net/npm/agent-referee-client@0.8.0/src/index.mjs\";\n\nconst PINNED_KEY = \"vM2GY6ZEYc/omRlIFrzu0TaMGtjHXQtchg9d7lPKkTY=\";\nconst OFFICIAL = [\"https://agentreferee.ai\", \"https://agent-referee.fairplayclub.workers.dev\"];\n\n// ?api= points the page at staging or a local test instance. \"Receipt checks out\" still only ever means the\n// official key; a test instance's receipts are labelled \"not an official receipt\" in the result itself.\n// Only known test addresses are accepted, so a crafted link can't send what a visitor types to someone else's server.\nconst TEST_APIS = [\"https://agent-referee-staging.fairplayclub.workers.dev\"];\nconst isLocal = (u) => /^http:\\/\\/(127\\.0\\.0\\.1|localhost)(:\\d+)?$/.test(u);\nconst params = new URLSearchParams(location.search);\nconst asked = (params.get(\"api\") || OFFICIAL[0]).replace(/\\/$/, \"\");\nconst refused = !(OFFICIAL.includes(asked) || TEST_APIS.includes(asked) || isLocal(asked));\nconst API = refused ? OFFICIAL[0] : asked;\nconst official = OFFICIAL.includes(API);\nlet KEYS = [PINNED_KEY];\nconst $ = (id) => document.getElementById(id);\nconst words = (v) => String(v ?? \"?\").replaceAll(\"_\", \" \");\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[c]);\n\nasync function api(method, path, body) {\n  let r;\n  try {\n    r = await fetch(API + path, { method, headers: body ? { \"content-type\": \"application/json\", accept: \"application/json\" } : { accept: \"application/json\" }, body: body ? JSON.stringify(body) : undefined });\n  } catch (e) {\n    throw new Error(\"Couldn't reach the service. Check your connection, or the status page: https://stats.uptimerobot.com/dh6sVMvo3W\");\n  }\n  const data = await r.json().catch(() => undefined);\n  if (r.ok && (data === undefined || typeof data !== \"object\" || data === null)) throw new Error(\"The service sent an answer this page can't read. Try again in a moment.\");\n  if (!r.ok) {\n    const said = typeof data?.error === \"string\" ? data.error : \"\";\n    const e = new Error(said || (r.status === 429 ? \"Today's free allowance from your connection is used up, or the service is limiting requests. Try again tomorrow (UTC).\" : `The service answered ${r.status}.`));\n    e.status = r.status;\n    e.retry = (data.retry_after_s ?? Number(r.headers.get(\"retry-after\"))) || null;\n    throw e;\n  }\n  return data;\n}\n\n// Service status and the signing key in use.\nconst disableAll = () => { for (const b of document.querySelectorAll(\"button.go\")) b.disabled = true; };\nlet keysReady = official || refused;\nif (!keysReady) disableAll(); // in test mode, nothing runs until the test service's key is known\n(async () => {\n  if (refused) {\n    $(\"test-notice\").hidden = false;\n    $(\"test-notice\").textContent = `This link asked the page to use ${asked}, which isn't an Agent Referee address, so the page ignored it and uses the official service.`;\n  } else if (!official) {\n    try {\n      const k = await api(\"GET\", \"/pubkey\");\n      if (typeof k.public_key !== \"string\" || !k.public_key) throw new Error(\"no key\");\n      KEYS = [k.public_key, ...(Array.isArray(k.history) ? k.history : []).map((h) => h?.public_key).filter((x) => typeof x === \"string\")];\n      keysReady = true;\n      for (const b of document.querySelectorAll(\"button.go\")) b.disabled = false;\n      $(\"test-notice\").textContent = `Test mode: this page talks to ${API}, not the official service. Receipts it signs are labelled \"not an official receipt\".`;\n    } catch {\n      KEYS = [];\n      disableAll();\n      $(\"test-notice\").textContent = `Test mode: couldn't read ${API}'s signing key, so nothing can be checked. The buttons are off.`;\n    }\n    $(\"test-notice\").hidden = false;\n  }\n  $(\"key-shown\").textContent = KEYS[0] || \"(unknown)\";\n  try {\n    const h = await api(\"GET\", \"/health\");\n    const s = h.status || \"ok\";\n    $(\"health-dot\").className = \"dot \" + (s === \"ok\" ? \"ok\" : s === \"down\" ? \"bad\" : \"warn\");\n    const reasons = Array.isArray(h.reasons) ? h.reasons.map(String).join(\", \") : \"\";\n    $(\"health\").textContent = s === \"ok\" ? \"Service is up\" : s === \"paused\" ? \"Paused for a moment\" : s === \"degraded\" ? \"Up, with problems\" + (reasons ? \": \" + reasons : \"\") : \"Service is down\";\n  } catch {\n    $(\"health-dot\").className = \"dot bad\";\n    $(\"health\").textContent = \"Couldn't reach the service\";\n  }\n  // The free allowance as the service publishes it (GET /reviewers), not a number written into this page.\n  try {\n    const per = (await api(\"GET\", \"/reviewers\")).free?.per_address_per_day;\n    if (Number.isInteger(per?.review) && Number.isInteger(per?.[\"review-3\"]))\n      $(\"r-allowance\").textContent = `${per.review} single review${per.review === 1 ? \"\" : \"s\"} and ${per[\"review-3\"]} three-reviewer review${per[\"review-3\"] === 1 ? \"\" : \"s\"} a day`;\n  } catch {}\n})();\n\n// Tabs: click, or arrow keys / Home / End between them (one tab stop for the whole row).\nconst tabs = [...document.querySelectorAll(\"nav [role=tab]\")];\nfunction selectTab(b, focus) {\n  for (const x of tabs) { x.setAttribute(\"aria-selected\", String(x === b)); x.tabIndex = x === b ? 0 : -1; }\n  for (const p of document.querySelectorAll(\"section.panel\")) p.hidden = p.id !== b.getAttribute(\"aria-controls\");\n  if (focus) b.focus();\n}\nfor (const b of tabs) {\n  b.addEventListener(\"click\", () => selectTab(b, false));\n  b.addEventListener(\"keydown\", (e) => {\n    const i = tabs.indexOf(b);\n    const to = { ArrowRight: (i + 1) % tabs.length, ArrowLeft: (i - 1 + tabs.length) % tabs.length, Home: 0, End: tabs.length - 1 }[e.key];\n    if (to !== undefined) { e.preventDefault(); selectTab(tabs[to], true); }\n  });\n}\n\n// \"Receipt checks out\" only ever means: signed by the OFFICIAL key and the result recomputes. A receipt signed by a\n// test instance's key (?api=) says so in the headline itself, not just in the banner.\nfunction checkBox(check, extra = [], testKey = !official, note = \"\") {\n  const problems = [...(check.problems || []), ...extra];\n  const ok = check.ok === true && extra.length === 0;\n  if (!ok && problems.length === 0) problems.push(\"The check didn't complete, so this result can't be confirmed.\");\n  const head = !ok ? \"Receipt problem\" : testKey ? \"Checks out against the TEST service's key: not an official receipt\" : \"Receipt checks out\";\n  return `<div class=\"check\"><strong class=\"${ok && !testKey ? \"ok\" : ok ? \"warn\" : \"bad\"}\">${head}</strong>\n    ${ok && !testKey ? \"<p class='muted'>Signed with Agent Referee's official key, unchanged since, and the result recomputes from what's in it.</p>\" : \"\"}\n    ${ok && note ? `<p class=\"warn\">${esc(note)}</p>` : \"\"}\n    ${problems.length ? `<ul>${problems.map((p) => `<li>${esc(p)}</li>`).join(\"\")}</ul>` : \"\"}\n    ${check.trusts?.length ? `<details><summary>What you're taking on trust</summary><ul>${check.trusts.map((t) => `<li>${esc(t)}</li>`).join(\"\")}</ul></details>` : \"\"}</div>`;\n}\n\nconst blobs = {};\nfunction receiptTools(receipt, name, slot) {\n  name = String(name).replace(/[^A-Za-z0-9-]/g, \"\").slice(0, 60) || \"receipt\";\n  const json = JSON.stringify(receipt, null, 2);\n  if (blobs[slot]) URL.revokeObjectURL(blobs[slot]);\n  const url = (blobs[slot] = URL.createObjectURL(new Blob([json], { type: \"application/json\" })));\n  return `<a class=\"small\" download=\"${esc(name)}.json\" href=\"${url}\">Download receipt</a>\n    <details><summary>Show receipt</summary><pre>${esc(json)}</pre></details>`;\n}\n\nfunction errorHtml(e) {\n  let msg = e.message || String(e);\n  const retry = e.retry ?? e.body?.retry_after_s; // the page's own requests, or the JS client's RefereeError\n  if (e.status === 503 && retry) msg += ` Try again in about ${Math.ceil(retry)} seconds.`;\n  return `<p class=\"err\">${esc(msg)}</p>`;\n}\n\n// 1. Free review.\nconst countIt = () => {\n  const n = $(\"r-task\").value.length + $(\"r-output\").value.length;\n  $(\"r-count\").textContent = n ? `${n.toLocaleString()} characters` : \"\";\n};\n$(\"r-task\").addEventListener(\"input\", countIt);\n$(\"r-output\").addEventListener(\"input\", countIt);\n$(\"r-go\").addEventListener(\"click\", async () => {\n  const task = $(\"r-task\").value, output = $(\"r-output\").value, tier = $(\"r-tier\").value, panel = $(\"r-panel\").value || undefined;\n  if (!task.trim() || !output.trim()) { $(\"r-out\").innerHTML = errorHtml(new Error(\"Fill in both the task and the output.\")); return; }\n  $(\"r-go\").disabled = true;\n  $(\"r-out\").innerHTML = `<p class=\"muted\">Reviewing… usually seconds, sometimes up to a few minutes.</p>`;\n  try {\n    const r = await api(\"POST\", `/free/${tier}`, { task, output, ...(panel ? { panel } : {}) });\n    const pp = r.receipt?.payload;\n    if (pp?.receipt_format !== undefined) throw new Error(\"The service answered with a receipt format this page can't check yet, so nothing was confirmed.\");\n    if (!pp || typeof r.receipt.signature !== \"string\" || !Array.isArray(pp.votes) || typeof pp.result?.verdict !== \"string\")\n      throw new Error(\"The service's answer didn't include a complete receipt, so there's nothing to check. Your free review may not have been used; try again.\");\n    const ref = new AR.AgentReferee({ url: API, publicKeys: KEYS });\n    const check = await ref.verifyReview(r.receipt, { task, output, tier, panel });\n    const p = r.receipt.payload;\n    const extra = p.funding === \"free\" && p.payer == null ? [] : [\"This receipt isn't marked as a free review.\"];\n    const good = check.ok && extra.length === 0;\n    // The check comes first: if it fails, what follows is the service's unverified answer, and says so.\n    $(\"r-out\").innerHTML = `${checkBox(check, extra)}\n      ${good ? \"\" : `<p class=\"bad\"><strong>Unverified:</strong> the result below couldn't be confirmed from the receipt.</p>`}\n      <p class=\"verdict ${esc(p.result.verdict)}\">${esc(words(p.result.verdict))}</p>\n      <div class=\"votes\">${p.votes.map((v) => `<div class=\"vote\"><strong class=\"${esc(v?.verdict)}\">${esc(words(v?.verdict))}</strong> · <code>${esc(v?.model)}</code> <span class=\"muted\">(${esc(v?.confidence)} confidence)</span>\n        ${Array.isArray(v?.issues) && v.issues.length ? `<ul>${v.issues.map((i) => `<li>${esc(i)}</li>`).join(\"\")}</ul>` : \"\"}\n        ${v?.reasoning ? `<p class=\"muted\">${esc(v.reasoning)}</p>` : \"\"}</div>`).join(\"\")}</div>\n      ${receiptTools(r.receipt, \"review-\" + p.review_id, \"review\")}\n      ${Number.isInteger(r.free?.left_today) ? `<p class=\"muted\">Free ${tier === \"review-3\" ? \"three-reviewer reviews\" : \"single reviews\"} left today: ${r.free.left_today}.</p>` : \"\"}\n      <p class=\"muted\">A review is what these models think, not a guarantee the work is right.</p>`;\n  } catch (e) {\n    $(\"r-out\").innerHTML = errorHtml(e);\n  } finally {\n    $(\"r-go\").disabled = false;\n  }\n});\n\n// 2. Demo match: both seats play in this page.\n$(\"m-tier\").addEventListener(\"change\", () => { $(\"m-odds\").hidden = $(\"m-tier\").value !== \"weighted\"; });\n$(\"m-go\").addEventListener(\"click\", async () => {\n  const tier = $(\"m-tier\").value;\n  const a = Math.min(99, Math.max(1, Math.round(Number($(\"m-alpha\").value) || 50)));\n  $(\"m-go\").disabled = true;\n  $(\"m-out\").innerHTML = `<p class=\"muted\">Both seats commit their secret seeds, then reveal them…</p>`;\n  try {\n    const ref = new AR.AgentReferee({ url: API, demo: true, publicKeys: KEYS, pollMs: 500 });\n    const spec = { tier, seats: [\"alpha\", \"beta\"], ...(tier === \"weighted\" ? { weights: { alpha: a, beta: 100 - a } } : {}) };\n    const m = await ref.create(spec);\n    const [sa, sb] = await Promise.all([ref.join(m.match_id, \"alpha\"), ref.join(m.match_id, \"beta\")]);\n    const [ra, rb] = await Promise.all([sa.play(), sb.play()]);\n    const problems = [...(ra.check?.problems ?? []).map((x) => \"alpha: \" + x), ...(rb.check?.problems ?? []).map((x) => \"beta: \" + x)];\n    if (AR.canonicalJson(ra.receipt) !== AR.canonicalJson(rb.receipt)) problems.push(\"The two seats were given different receipts.\");\n    const ok = !!(ra.check?.ok && rb.check?.ok) && problems.length === 0;\n    const out = ra.receipt?.payload?.outcome ?? {};\n    const weights = out.weights; // the odds as signed in the receipt, not as typed into this page\n    $(\"m-out\").innerHTML = `${checkBox({ ok, problems, trusts: ra.check?.trusts })}\n      ${ok ? \"\" : `<p class=\"bad\"><strong>Unverified:</strong> the result below couldn't be confirmed from the receipt.</p>`}\n      <p class=\"verdict\">${out.winner ? esc(out.winner) + \" wins\" : \"No winner\"}</p>\n      ${weights && typeof weights === \"object\" ? `<p class=\"muted\">Odds in the signed receipt: ${Object.entries(weights).map(([k, v]) => `${esc(k)} ${esc(v)}%`).join(\", \")}.</p>` : \"\"}\n      ${ok ? `<p class=\"muted\">Each seat recomputed the result from the receipt and confirmed its own secret number is in it as sent. In a real match, where each agent runs its own seat, that's what lets either side catch a changed outcome.</p>` : \"\"}\n      ${receiptTools(ra.receipt, \"match-\" + m.match_id, \"match\")}`;\n  } catch (e) {\n    $(\"m-out\").innerHTML = errorHtml(e);\n  } finally {\n    $(\"m-go\").disabled = false;\n  }\n});\n\n// 3. Check any receipt, offline.\n$(\"c-go\").addEventListener(\"click\", async () => {\n  try { await checkPasted(); } catch (e) { $(\"c-out\").innerHTML = errorHtml(new Error(\"That doesn't look like an Agent Referee receipt (\" + (e.message || e) + \").\")); }\n});\nasync function checkPasted() {\n  let receipt;\n  if (!$(\"c-receipt\").value.trim()) { $(\"c-out\").innerHTML = errorHtml(new Error(\"Paste a receipt first.\")); return; }\n  try { receipt = JSON.parse($(\"c-receipt\").value); } catch { $(\"c-out\").innerHTML = errorHtml(new Error(\"That isn't valid JSON.\")); return; }\n  if (!receipt || typeof receipt !== \"object\" || Array.isArray(receipt) || typeof receipt.signature !== \"string\" || typeof receipt.payload !== \"object\" || !receipt.payload) {\n    $(\"c-out\").innerHTML = errorHtml(new Error(\"That doesn't look like an Agent Referee receipt: it needs a payload and a signature.\"));\n    return;\n  }\n  const p = receipt.payload;\n  // Receipt formats this page doesn't know (multi-part reviews and judging are coming) are refused, never checked\n  // the old way: an old check could recompute the verdict and miss what the new format changed.\n  if (p.receipt_format !== undefined) {\n    $(\"c-out\").innerHTML = errorHtml(new Error(`This receipt uses a newer format (\"${String(p.receipt_format).slice(0, 40)}\") that this page can't check yet. Nothing was confirmed.`));\n    return;\n  }\n  // The official key decides. Only in test mode (?api=) is the test instance's key tried as well, and labelled.\n  const officialSig = await AR.verifySignature(receipt, [PINNED_KEY]);\n  const testSig = !officialSig && !official && (await AR.verifySignature(receipt, KEYS));\n  const sigProblem = officialSig || testSig ? [] : [official\n    ? \"The signature doesn't match Agent Referee's key: this receipt wasn't issued by it, or it was changed.\"\n    : \"The signature doesn't match Agent Referee's key or the test service's key: it wasn't issued by either, or it was changed.\"];\n  let check, headline, note = \"\";\n  if (p.type !== undefined && p.type !== \"review\") {\n    $(\"c-out\").innerHTML = errorHtml(new Error(`This page can't check \"${String(p.type).slice(0, 40)}\" receipts yet. Nothing was confirmed.`));\n    return;\n  }\n  if (p.type === \"review\") {\n    const task = $(\"c-task\").value, output = $(\"c-output\").value;\n    check = await AR.verifyReviewOutcome(receipt, { ...(task ? { task } : {}), ...(output ? { output } : {}) });\n    headline = `A ${esc(p.tier)} review: <span class=\"${esc(p.result?.verdict)}\">${esc(words(p.result?.verdict))}</span>`;\n    if (!task || !output) note = \"The task and output weren't given, so this doesn't confirm which work the review is about.\";\n  } else {\n    check = await AR.verifyOutcome(receipt);\n    const o = p?.outcome || {};\n    headline = `A ${esc(p?.tier ?? \"?\")} match${p?.demo ? \" (demo)\" : \"\"}: ${o.winner ? esc(o.winner) + \" won\" : o.mistrial ? \"mistrial\" : esc(o.result ?? \"\")}`;\n  }\n  const good = check.ok === true && sigProblem.length === 0;\n  $(\"c-out\").innerHTML = `${checkBox(check, sigProblem, !officialSig, note)}<p class=\"verdict\">${good ? \"\" : \"<span class='bad'>Unverified claim:</span> \"}${headline}</p>`;\n}\n</script>\n</body>\n</html>\n";
export const TRY_SCRIPT_HASHES = ["sha256-QiB9P1qPxotPPhViDQu5aPzfTijrwQ1dQOvCSgPnIuY="];
